-- Koha's status names and item status dates, with no patron
-- (docs/specs/circulacao/lost-items.md, items 17 and 18).
CREATE TABLE `borrowers` (`borrowernumber` int(11) NOT NULL, `cardnumber` varchar(32) DEFAULT NULL, PRIMARY KEY (`borrowernumber`));
CREATE TABLE `authorised_values` (`id` int(11) NOT NULL, `category` varchar(32) NOT NULL DEFAULT '', `authorised_value` varchar(80) NOT NULL DEFAULT '', `lib` varchar(200) DEFAULT NULL, `lib_opac` varchar(200) DEFAULT NULL, `imageurl` varchar(200) DEFAULT NULL, PRIMARY KEY (`id`));
INSERT INTO `authorised_values` VALUES (1,'LOST','1','Perdido',NULL,NULL),(2,'LOST','2',' Extraviado ',NULL,NULL),(3,'LOST','3','Perdido',NULL,NULL),(4,'LOST','100','Longe',NULL,NULL),(5,'LOST','x','Xis',NULL,NULL),(6,'DAMAGED','1','Danificado',NULL,NULL),(7,'WITHDRAWN','1','Baixa',NULL,NULL),(8,'NOT_LOAN','-1','Encomendado',NULL,NULL),(9,'NOT_LOAN','1','Referência',NULL,NULL),(10,'TURNOS','1','Manhã',NULL,NULL),(11,'DAMAGED','2','',NULL,NULL);
CREATE TABLE `items` (`itemnumber` int(11) NOT NULL AUTO_INCREMENT, `biblionumber` int(11) NOT NULL DEFAULT 0, `barcode` varchar(20) DEFAULT NULL, `damaged` tinyint(4) NOT NULL DEFAULT 0, `damaged_on` datetime DEFAULT NULL, `itemlost` tinyint(1) NOT NULL DEFAULT 0, `itemlost_on` datetime DEFAULT NULL, `withdrawn` tinyint(1) NOT NULL DEFAULT 0, `withdrawn_on` datetime DEFAULT NULL, PRIMARY KEY (`itemnumber`));
